control_statements.sql:
CREATE TABLE public.account (

    account_id bigint DEFAULT '0'::bigint NOT NULL,

    district_id bigint DEFAULT '0'::bigint,

    frequency text,

    date date

);

CREATE TABLE public.alignment (

    id bigint NOT NULL,

    alignment text

);

CREATE TABLE public.atom (

    atom_id text NOT NULL,

    molecule_id text,

    element text

);

CREATE TABLE public.attendance (

    link_to_event text NOT NULL,

    link_to_member text NOT NULL

);

CREATE TABLE public.attribute (

    id bigint NOT NULL,

    attribute_name text

);

CREATE TABLE public.badges (

    id bigint NOT NULL,

    userid bigint,

    name text,

    date timestamp with time zone

);

CREATE TABLE public.bond (

    bond_id text NOT NULL,

    molecule_id text,

    bond_type text

);

CREATE TABLE public.card (

    card_id bigint DEFAULT '0'::bigint NOT NULL,

    disp_id bigint,

    type text,

    issued date

);

CREATE TABLE public.client (

    client_id bigint NOT NULL,

    gender text,

    birth_date date,

    district_id bigint

);

CREATE TABLE public.colour (

    id bigint NOT NULL,

    colour text

);

CREATE TABLE public.connected (

    atom_id text NOT NULL,

    atom_id2 text NOT NULL,

    bond_id text

);

CREATE TABLE public.country (

    id bigint NOT NULL,

    name text

);

CREATE TABLE public.customers (

    customerid bigint NOT NULL,

    segment text,

    currency text

);

CREATE TABLE public.disp (

    disp_id bigint NOT NULL,

    client_id bigint,

    account_id bigint,

    type text

);

CREATE TABLE public.gasstations (

    gasstationid bigint NOT NULL,

    chainid bigint,

    country text,

    segment text

);

CREATE TABLE public.gender (

    id bigint NOT NULL,

    gender text

);

CREATE TABLE public.hero_attribute (

    hero_id bigint,

    attribute_id bigint,

    attribute_value bigint

);

CREATE TABLE public.hero_power (

    hero_id bigint,

    power_id bigint

);

CREATE TABLE public.league (

    id bigint NOT NULL,

    country_id bigint,

    name text

);

CREATE TABLE public.legalities (

    id bigint NOT NULL,

    format text,

    status text,

    uuid text

);

CREATE TABLE public.major (

    major_id text NOT NULL,

    major_name text,

    department text,

    college text

);

CREATE TABLE public.molecule (

    molecule_id text NOT NULL,

    label text

);

CREATE TABLE public.products (

    productid bigint NOT NULL,

    description text

);

CREATE TABLE public.publisher (

    id bigint NOT NULL,

    publisher_name text

);

CREATE TABLE public.race (

    id bigint NOT NULL,

    race text

);

CREATE TABLE public.rulings (

    id bigint NOT NULL,

    date date,

    text text,

    uuid text

);

CREATE TABLE public.seasons (

    year bigint DEFAULT '0'::bigint NOT NULL,

    url text DEFAULT ''::text

);

CREATE TABLE public.set_translations (

    id bigint NOT NULL,

    language text,

    setcode text,

    translation text

);

CREATE TABLE public.status (

    statusid bigint NOT NULL,

    status text DEFAULT ''::text

);

CREATE TABLE public.superpower (

    id bigint NOT NULL,

    power_name text

);

CREATE TABLE public.yearmonth (

    customerid bigint,

    date text,

    consumption real

);

